package com.travelbird.savedroute.service;
import com.travelbird.ai.service.AiPreviewService;import com.travelbird.savedroute.repository.AiPreviewSavedRouteRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiPreviewSavedRouteService{private final AiPreviewSavedRouteRepository routes;private final AiPreviewService previews;public AiPreviewSavedRouteService(AiPreviewSavedRouteRepository r,AiPreviewService p){routes=r;previews=p;}@Transactional public void save(Long uid,Long id){previews.makePermanent(uid,id);routes.savePreview(uid,id);}@Transactional public void cancel(Long uid,Long id){previews.get(uid,id);routes.deletePreview(uid,id);if(routes.countPreview(id)==0)previews.makeTemporary(uid,id);}}
